using System;
using System.Collections.Generic;

namespace SengokuChronicle.Domain
{
    /// <summary>
    /// One deterministic NPC autonomous-marriage opportunity. The proposal is a pure
    /// fact: it names the already-registered candidate and the facts the application
    /// layer needs to create a stable spouse. It never contains a name, ID or birth
    /// year for the new spouse, because those are generated by the settlement.
    /// </summary>
    public readonly struct NpcMarriageProposal
    {
        public NpcMarriageProposal(PersonId candidateId, PersonGender candidateGender,
            int candidateAge, int candidateBirthYear)
        {
            CandidateId = candidateId;
            CandidateGender = candidateGender;
            CandidateAge = candidateAge;
            CandidateBirthYear = candidateBirthYear;
        }

        public PersonId CandidateId { get; }
        public PersonGender CandidateGender { get; }
        /// <summary>Age at the annual settlement date, using the persisted birth year.</summary>
        public int CandidateAge { get; }
        public int CandidateBirthYear { get; }
    }

    /// <summary>
    /// M08A pure family-life-cycle rules: annual natural mortality and NPC autonomous
    /// marriage. Both plans read the live <see cref="SuccessionState"/> and never mutate
    /// it, so the monthly transaction can discard a plan without leaving partial family
    /// state. Every roll comes from the caller's persisted WorldSimulation stream.
    /// </summary>
    public static class FamilyLifeCycleRules
    {
        /// <summary>Permille denominator; 1000 keeps the 0.5% band exactly representable.</summary>
        public const int MortalityRollExclusiveMax = 1000;

        /// <summary>One 15% autonomous-marriage check per eligible person per year.</summary>
        public const int MarriageRollExclusiveMax = 100;
        public const int MarriagePercent = 15;

        /// <summary>Preferred maximum age difference between a candidate and a generated spouse.</summary>
        public const int MaximumSpouseAgeGap = 5;

        // Fixed design bands (GDD M08A). Values are per-mille: 5 = 0.5%, 10 = 1%, ...
        public const int ChildMortalityPermille = 5;
        public const int YoungAdultMortalityPermille = 5;
        public const int MiddleAgeMortalityPermille = 10;
        public const int SeniorMortalityPermille = 40;
        public const int ElderMortalityPermille = 120;
        public const int VeryOldMortalityPermille = 250;

        /// <summary>
        /// M08B food-shortage extension of the annual check: each complete band of three
        /// consecutive shortage months adds 50 permille, capped at +250 permille. A month
        /// that fully met the household demand resets the market's shortage count to zero.
        /// </summary>
        public const int ShortageMortalityBonusPerBandPermille = 50;
        public const int ShortageMonthsPerBand = 3;
        public const int MaximumShortageMortalityBonusPermille = 250;

        /// <summary>Bonus permille for a market shortage count; zero or negative means none.</summary>
        public static int MortalityBonusForFoodShortage(int consecutiveShortageMonths)
        {
            if (consecutiveShortageMonths < ShortageMonthsPerBand)
                return 0;

            long bonus = (long)(consecutiveShortageMonths / ShortageMonthsPerBand) *
                         ShortageMortalityBonusPerBandPermille;
            return bonus > MaximumShortageMortalityBonusPermille
                ? MaximumShortageMortalityBonusPermille
                : (int)bonus;
        }

        /// <summary>
        /// True only for the one monthly step that crosses December into the next
        /// January. All annual settlement happens on that single boundary.
        /// </summary>
        public static bool IsAnnualBoundary(GameDate currentDate, GameDate nextDate) =>
            currentDate.IsValid && nextDate.IsValid &&
            currentDate.Month == 12 && nextDate.Month == 1 &&
            nextDate.Year == currentDate.Year + 1 && nextDate > currentDate;

        /// <summary>
        /// Fixed age-band mortality used by the annual check. Ages below zero (only
        /// reachable from a corrupt birth year) never die instead of producing a
        /// negative probability.
        /// </summary>
        public static int MortalityPermilleForAge(int age)
        {
            if (age < 0)
                return 0;
            if (age <= 14)
                return ChildMortalityPermille;      // 0–14 岁 0.5%
            if (age <= 39)
                return YoungAdultMortalityPermille; // 15–39 岁 0.5%
            if (age <= 59)
                return MiddleAgeMortalityPermille;  // 40–59 岁 1%
            if (age <= 69)
                return SeniorMortalityPermille;     // 60–69 岁 4%
            if (age <= 79)
                return ElderMortalityPermille;      // 70–79 岁 12%
            return VeryOldMortalityPermille;        // 80 岁以上 25%
        }

        /// <summary>
        /// Snapshot of every living family member in ordinal person-ID order. The
        /// monthly transaction captures this before any birth is applied, so a newborn
        /// can never be included in the same annual mortality list.
        /// </summary>
        public static IReadOnlyList<PersonId> CaptureDeathCandidateIds(SuccessionState state)
        {
            var candidates = new List<PersonId>();
            if (state == null || state.World == null)
                return candidates.AsReadOnly();

            foreach (PersonState person in state.World.Persons)
            {
                if (!state.World.Family.IsMember(person.Id))
                    continue;
                if (!state.World.TryGetLife(person.Id, out SuccessionPersonLife life) || !life.Alive)
                    continue;
                candidates.Add(person.Id);
            }
            return candidates.AsReadOnly();
        }

        /// <summary>
        /// Plans one annual natural-death settlement. The candidate snapshot is taken
        /// here; use the candidate overload when the caller must freeze the roster
        /// before an earlier monthly phase (births) mutates it.
        /// </summary>
        public static IReadOnlyList<PersonId> PlanNaturalDeaths(SuccessionState state,
            GameDate currentDate, GameDate nextDate, DeterministicRandomStream random) =>
            PlanNaturalDeaths(CaptureDeathCandidateIds(state), state, currentDate, nextDate,
                random);

        /// <summary>
        /// Plans natural deaths for one frozen candidate list. A non-boundary month
        /// consumes no random values at all. On a boundary every still-living candidate
        /// consumes exactly one WorldSimulation roll in ordinal person-ID order, so the
        /// same save and seed always produce the same death set. Candidates that are no
        /// longer living or no longer members are skipped without consuming a roll; the
        /// monthly transaction only passes a snapshot taken before the settlement.
        /// </summary>
        public static IReadOnlyList<PersonId> PlanNaturalDeaths(
            IReadOnlyList<PersonId> candidates, SuccessionState state, GameDate currentDate,
            GameDate nextDate, DeterministicRandomStream random) =>
            PlanNaturalDeaths(candidates, state, currentDate, nextDate, random, 0);

        /// <summary>
        /// Plans natural deaths with the approved M08B food-shortage bonus added to every
        /// age probability. The bonus never changes the draw order: each still-living
        /// candidate still consumes exactly one WorldSimulation roll, and the combined
        /// probability is clamped to 1000 permille.
        /// </summary>
        public static IReadOnlyList<PersonId> PlanNaturalDeaths(
            IReadOnlyList<PersonId> candidates, SuccessionState state, GameDate currentDate,
            GameDate nextDate, DeterministicRandomStream random, int mortalityBonusPermille)
        {
            var deaths = new List<PersonId>();
            if (candidates == null || state == null || state.World == null || random == null ||
                !IsAnnualBoundary(currentDate, nextDate))
                return deaths.AsReadOnly();

            int bonus = mortalityBonusPermille > 0
                ? Math.Min(mortalityBonusPermille, MortalityRollExclusiveMax)
                : 0;

            for (int i = 0; i < candidates.Count; i++)
            {
                PersonId personId = candidates[i];
                if (personId.IsEmpty ||
                    !state.World.TryGetPerson(personId, out _) ||
                    !state.World.Family.IsMember(personId) ||
                    !state.World.TryGetLife(personId, out SuccessionPersonLife life) ||
                    !life.Alive)
                    continue;

                if (!random.TryNextInt(MortalityRollExclusiveMax, out int roll))
                    continue;

                int mortality = Math.Min(MortalityRollExclusiveMax,
                    MortalityPermilleForAge(life.AgeAt(nextDate)) + bonus);
                if (roll < mortality)
                    deaths.Add(personId);
            }

            return deaths.AsReadOnly();
        }

        /// <summary>
        /// Snapshot of every family member who may marry at this annual boundary, in
        /// ordinal person-ID order: living members other than the player-controlled
        /// head who are adult at <paramref name="nextDate"/>, have a known gender and
        /// have no living formal spouse. The monthly transaction captures this before
        /// the settlement applies any birth or death, so a person widowed by this same
        /// settlement was recorded with a living spouse and only becomes eligible at a
        /// later annual settlement. A spouse generated this year is never in the list.
        /// </summary>
        public static IReadOnlyList<PersonId> CaptureMarriageCandidateIds(
            SuccessionState state, GameDate nextDate)
        {
            var candidates = new List<PersonId>();
            if (state == null || state.World == null || !nextDate.IsValid)
                return candidates.AsReadOnly();

            HashSet<PersonId> hasLivingSpouse = BuildLivingSpouseIds(state);
            foreach (PersonState person in state.World.Persons)
            {
                if (person.Id == state.HeadPersonId)
                    continue;
                if (!state.World.Family.IsMember(person.Id))
                    continue;
                if (!state.World.TryGetLife(person.Id, out SuccessionPersonLife life) ||
                    !life.Alive)
                    continue;
                if (person.Gender != PersonGender.Male && person.Gender != PersonGender.Female)
                    continue;
                if (life.AgeAt(nextDate) < state.AdulthoodAge)
                    continue;
                if (hasLivingSpouse.Contains(person.Id))
                    continue;
                candidates.Add(person.Id);
            }
            return candidates.AsReadOnly();
        }

        /// <summary>
        /// Plans NPC autonomous marriages for one annual boundary from a candidate
        /// snapshot taken when the settlement began. Use the candidate overload when an
        /// earlier monthly phase (births or deaths) already mutated the family, so a
        /// newly widowed person cannot remarry in the same settlement. Each still-living
        /// candidate consumes exactly one roll in snapshot order and at most one proposal
        /// is produced per candidate. No fertility-age filter is applied.
        /// </summary>
        public static IReadOnlyList<NpcMarriageProposal> PlanNpcMarriages(
            SuccessionState state, GameDate currentDate, GameDate nextDate,
            DeterministicRandomStream random) =>
            PlanNpcMarriages(CaptureMarriageCandidateIds(state, nextDate), state,
                currentDate, nextDate, random);

        /// <summary>
        /// Plans marriages for one frozen candidate list. Eligibility, including the
        /// living-spouse test, is decided entirely by the snapshot; only candidates who
        /// died or left the family during the same settlement are skipped here, and they
        /// consume no roll so the replay order stays deterministic. A candidate promoted
        /// to head by this settlement's succession is skipped as well, because the head
        /// is player-controlled and never marries autonomously.
        /// </summary>
        public static IReadOnlyList<NpcMarriageProposal> PlanNpcMarriages(
            IReadOnlyList<PersonId> candidates, SuccessionState state, GameDate currentDate,
            GameDate nextDate, DeterministicRandomStream random)
        {
            var proposals = new List<NpcMarriageProposal>();
            if (candidates == null || state == null || state.World == null || random == null ||
                !IsAnnualBoundary(currentDate, nextDate))
                return proposals.AsReadOnly();

            for (int i = 0; i < candidates.Count; i++)
            {
                PersonId personId = candidates[i];
                if (personId.IsEmpty ||
                    !state.World.TryGetPerson(personId, out PersonState person) ||
                    person.Id == state.HeadPersonId ||
                    !state.World.Family.IsMember(personId) ||
                    !state.World.TryGetLife(personId, out SuccessionPersonLife life) ||
                    !life.Alive ||
                    (person.Gender != PersonGender.Male &&
                     person.Gender != PersonGender.Female))
                    continue;

                int age = life.AgeAt(nextDate);
                if (age < state.AdulthoodAge)
                    continue;

                if (!random.TryNextInt(MarriageRollExclusiveMax, out int roll))
                    continue;
                if (roll >= MarriagePercent)
                    continue;

                proposals.Add(new NpcMarriageProposal(person.Id, person.Gender, age,
                    life.BirthYear));
            }

            return proposals.AsReadOnly();
        }

        /// <summary>Living endpoints of every recorded formal spouse fact.</summary>
        private static HashSet<PersonId> BuildLivingSpouseIds(SuccessionState state)
        {
            var ids = new HashSet<PersonId>();
            IReadOnlyList<KinshipLink> links = state.World.Kinship.Links;
            for (int i = 0; i < links.Count; i++)
            {
                KinshipLink link = links[i];
                if (link.Type != KinshipType.Spouse)
                    continue;
                if (!state.World.IsLiving(link.From) || !state.World.IsLiving(link.To))
                    continue;
                ids.Add(link.From);
                ids.Add(link.To);
            }
            return ids;
        }
    }
}
